<?php
defined('ABSPATH')||exit;
final class SRL_Plugin{
 public static function activate(){if(!class_exists('SVW_Helpers')){deactivate_plugins(plugin_basename(SRL_FILE));wp_die('Activate File 10 first.',array('back_link'=>true));}$a=get_role('administrator');if($a)$a->add_cap('manage_reels');global$wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE {$wpdb->prefix}srl_history (id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,reel_id bigint unsigned NOT NULL,progress int unsigned NOT NULL DEFAULT 0,completed tinyint unsigned NOT NULL DEFAULT 0,replays int unsigned NOT NULL DEFAULT 0,updated_at datetime NOT NULL,PRIMARY KEY (id),UNIQUE KEY user_reel (user_id,reel_id)) {$c};");$spf=(array)get_option('spf_page_map',array());$m=array();$m['feed']=self::page(!empty($spf['reels'])?absint($spf['reels']):0,'Reels','reels','[srl_reels]');$m['create']=self::page(0,'Create Reel','create-reel','[srl_create]');$m['saved']=self::page(0,'Saved Reels','saved-reels','[srl_saved]');$m['history']=self::page(0,'Recently Watched Reels','reel-history','[srl_history]');update_option('srl_page_map',$m,false);$spf['reels']=$m['feed'];update_option('spf_page_map',$spf,false);set_transient('srl_notice','1',120);}
 private static function page($id,$title,$slug,$code){$p=$id?get_post($id):get_page_by_path($slug);if($p instanceof WP_Post){if(get_post_meta($p->ID,'_spf_managed_page',true)||get_post_meta($p->ID,'_srl_managed',true)||false!==strpos($p->post_content,'[sabri_platform_module')){wp_update_post(array('ID'=>$p->ID,'post_content'=>$code));update_post_meta($p->ID,'_srl_managed','1');}return$p->ID;}$id=wp_insert_post(array('post_title'=>$title,'post_name'=>$slug,'post_content'=>$code,'post_status'=>'publish','post_type'=>'page'));update_post_meta($id,'_srl_managed','1');return$id;}
 public static function deactivate(){}
 public function run(){add_shortcode('srl_reels',array($this,'feed'));add_shortcode('srl_create',array($this,'form'));add_shortcode('srl_saved',array($this,'saved'));add_shortcode('srl_history',array($this,'history'));add_action('admin_post_srl_submit',array($this,'submit'));add_action('wp_ajax_srl_progress',array($this,'progress'));add_action('admin_menu',array($this,'menu'));add_action('admin_post_srl_review',array($this,'review'));add_action('wp_enqueue_scripts',array($this,'assets'));add_filter('wp_robots',array($this,'robots'));}
 public function feed(){$sort=isset($_GET['reel_sort'])?sanitize_key(wp_unslash($_GET['reel_sort'])):'trending';$args=array('post_type'=>SVW_Helpers::TYPE,'post_status'=>'publish','posts_per_page'=>40,'meta_query'=>array(array('key'=>'_svw_is_reel','value'=>'1')));$args['orderby']='latest'===$sort?'date':'meta_value_num';if('latest'!==$sort)$args['meta_key']='_svw_score';$items=get_posts($args);$m=(array)get_option('srl_page_map',array());ob_start();?><main class="srl-shell"><?php echo SVW_Helpers::nav();?><header class="srl-head"><h1>Reels</h1><p>Swipe through verified educational Reels. Every Reel is between 1 and 10 minutes.</p><a href="<?php echo esc_url($m['create']?get_permalink($m['create']):'#');?>">Create Reel</a></header><div class="srl-feed"><?php foreach($items as$r):$id=$r->ID;$author=$r->post_author;?><article class="srl-reel" data-reel="<?php echo absint($id);?>" data-duration="<?php echo absint(SVW_Helpers::meta($id,'duration'));?>"><div class="srl-player"><?php echo SVW_Helpers::embed($id);?></div><div class="srl-overlay"><span><?php echo esc_html(SVW_Helpers::category($id));?></span><h2><?php echo esc_html($r->post_title);?></h2><p><?php echo esc_html($r->post_excerpt);?></p><b><?php echo esc_html(get_the_author_meta('display_name',$author));?> · <?php echo SVW_Helpers::founder($author)?'Verified Founder':'Verified Doctor';?></b><?php echo SVW_Interactions::buttons($id);?><a href="<?php echo esc_url(get_permalink($id));?>">Open Reel Page</a></div></article><?php endforeach;?></div></main><?php return ob_get_clean();}
 public function form(){if(!is_user_logged_in()||!SVW_Helpers::can_submit())return'<div class="srl-note">Verified doctor access is required.</div>';ob_start();?><main class="srl-shell"><h1>Create Reel</h1><p>Final duration rule: minimum 1 minute and maximum 10 minutes.</p><form class="srl-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="srl_submit"><?php wp_nonce_field('srl_submit','srl_nonce');?><label>Reel title<input name="title" required></label><label>Short caption<textarea name="caption" maxlength="500" required></textarea></label><label>Category<select name="category"><?php foreach(SVW_Helpers::categories()as$k=>$v):?><option value="<?php echo esc_attr($k);?>"><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Source<select name="source"><option value="youtube">YouTube Shorts</option><option value="vimeo">Vimeo</option><option value="local">Local vertical video</option></select></label><label>Video URL<input type="url" name="video_url"></label><label>Local video<input type="file" name="local_video" accept="video/mp4,video/webm,video/ogg"></label><label>Cover image<input type="file" name="thumbnail" accept="image/jpeg,image/png,image/webp" required></label><label>Duration<input name="duration" value="00:01:00" pattern="00:(0[1-9]|10):[0-5][0-9]" required><small>Between 00:01:00 and 00:10:00.</small></label><label>On-screen caption<textarea name="transcript" required></textarea></label><label>References<textarea name="references" required></textarea></label><label>Medical safety notice<textarea name="safety" required></textarea></label><label><input type="checkbox" name="copyright" required> I own or am authorized to publish this Reel.</label><label><input type="checkbox" name="medical" required> I confirm the medical-safety and educational rules.</label><label><input type="checkbox" name="case" value="1"> Patient Case identity removed and consent obtained, when applicable.</label><button>Submit Reel</button></form></main><?php return ob_get_clean();}
 public function submit(){if(!is_user_logged_in()||!SVW_Helpers::can_submit())wp_die('Access denied.');check_admin_referer('srl_submit','srl_nonce');$duration=SVW_Helpers::parse_duration(sanitize_text_field(wp_unslash($_POST['duration']??'')));if($duration<60||$duration>600)wp_die('A Reel must be between 1 and 10 minutes.');$title=sanitize_text_field(wp_unslash($_POST['title']??''));$caption=sanitize_textarea_field(wp_unslash($_POST['caption']??''));$cat=sanitize_title(wp_unslash($_POST['category']??''));$source=sanitize_key(wp_unslash($_POST['source']??''));$url=esc_url_raw(wp_unslash($_POST['video_url']??''));$trans=sanitize_textarea_field(wp_unslash($_POST['transcript']??''));$refs=sanitize_textarea_field(wp_unslash($_POST['references']??''));$safe=sanitize_textarea_field(wp_unslash($_POST['safety']??''));if(!$title||!$caption||!isset(SVW_Helpers::categories()[$cat])||!$trans||!$refs||!$safe||empty($_POST['copyright'])||empty($_POST['medical']))wp_die('Complete every required field.');if('patient-cases'===$cat&&empty($_POST['case']))wp_die('Patient Case consent and anonymity confirmation is required.');$id=wp_insert_post(array('post_type'=>SVW_Helpers::TYPE,'post_status'=>SVW_Helpers::initial_status(),'post_title'=>$title,'post_excerpt'=>$caption,'post_content'=>$caption,'post_author'=>get_current_user_id(),'comment_status'=>'open'));wp_set_object_terms($id,$cat,SVW_Helpers::TAX);foreach(array('is_reel'=>1,'source'=>$source,'video_url'=>$url,'duration'=>$duration,'transcript'=>$trans,'references'=>$refs,'safety'=>$safe,'views'=>0,'likes'=>0,'dislikes'=>0,'score'=>0)as$k=>$v)update_post_meta($id,'_svw_'.$k,$v);require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';if('local'===$source){$a=media_handle_upload('local_video',$id,array(),array('test_form'=>false,'mimes'=>array('mp4'=>'video/mp4','webm'=>'video/webm','ogv'=>'video/ogg')));if(is_wp_error($a)){wp_delete_post($id,true);wp_die('Video upload failed.');}update_post_meta($id,'_svw_attachment_id',$a);}$t=media_handle_upload('thumbnail',$id,array(),array('test_form'=>false,'mimes'=>array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp')));if(!is_wp_error($t))set_post_thumbnail($id,$t);wp_safe_redirect(get_permalink((array_values((array)get_option('srl_page_map')))[0]));exit;}
 public function progress(){check_ajax_referer('srl_progress','nonce');if(!is_user_logged_in())wp_send_json_error();$id=absint($_POST['reel']??0);$p=min(600,max(0,absint($_POST['progress']??0)));if('1'!==SVW_Helpers::meta($id,'is_reel','0'))wp_send_json_error();global$wpdb;$duration=absint(SVW_Helpers::meta($id,'duration'));$wpdb->replace($wpdb->prefix.'srl_history',array('user_id'=>get_current_user_id(),'reel_id'=>$id,'progress'=>$p,'completed'=>$p>=$duration*.9?1:0,'replays'=>0,'updated_at'=>current_time('mysql',true)),array('%d','%d','%d','%d','%d','%s'));wp_send_json_success();}
 public function saved(){return $this->list_page('Saved Reels',"SELECT video_id FROM %ssvw_saves WHERE user_id=%%d");}public function history(){return $this->list_page('Recently Watched Reels',"SELECT reel_id FROM %ssrl_history WHERE user_id=%%d ORDER BY updated_at DESC");}private function list_page($title,$sql){if(!is_user_logged_in())return'<div>Log in first.</div>';global$wpdb;$q=sprintf($sql,$wpdb->prefix);$ids=$wpdb->get_col($wpdb->prepare($q,get_current_user_id()));$items=get_posts(array('post_type'=>SVW_Helpers::TYPE,'post_status'=>'publish','post__in'=>$ids?:array(0),'meta_key'=>'_svw_is_reel','meta_value'=>'1','posts_per_page'=>100));$out='<main class="srl-shell"><h1>'.esc_html($title).'</h1>';foreach($items as$i)$out.='<p><a href="'.esc_url(get_permalink($i)).'">'.esc_html($i->post_title).'</a></p>';return$out.'</main>';}
 public function menu(){add_menu_page('Reels Management','Reels Management','manage_reels','reels-management',array($this,'admin'),'dashicons-format-video',31);}public function admin(){$items=get_posts(array('post_type'=>SVW_Helpers::TYPE,'post_status'=>array('pending','publish','draft','private'),'posts_per_page'=>200,'meta_key'=>'_svw_is_reel','meta_value'=>'1'));?><div class="wrap"><h1>Reels Management</h1><table class="widefat striped"><?php foreach($items as$i):?><tr><td><?php echo esc_html($i->post_title);?></td><td><?php echo esc_html(get_post_status($i));?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="srl_review"><input type="hidden" name="id" value="<?php echo absint($i->ID);?>"><?php wp_nonce_field('srl_review_'.$i->ID);?><select name="status"><option value="publish">Publish</option><option value="draft">Reject</option><option value="private">Hide</option></select><button>Apply</button></form></td></tr><?php endforeach;?></table></div><?php }public function review(){if(!current_user_can('manage_reels'))wp_die('Denied');$id=absint($_POST['id']??0);check_admin_referer('srl_review_'.$id);$s=sanitize_key(wp_unslash($_POST['status']??''));if(!in_array($s,array('publish','draft','private'),true))wp_die('Invalid');wp_update_post(array('ID'=>$id,'post_status'=>$s));wp_safe_redirect(admin_url('admin.php?page=reels-management'));exit;}
 public function assets(){global$post;$m=(array)get_option('srl_page_map',array());if(!($post instanceof WP_Post&&in_array($post->ID,array_map('absint',$m),true)))return;wp_enqueue_style('srl',SRL_URL.'assets/reels.css',array(),SRL_VERSION);wp_enqueue_script('srl',SRL_URL.'assets/reels.js',array(),SRL_VERSION,true);wp_localize_script('srl','srlData',array('url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('srl_progress')));}public function robots($r){$m=(array)get_option('srl_page_map',array());foreach(array('saved','history')as$k)if(!empty($m[$k])&&is_page($m[$k])){$r['noindex']=true;$r['noarchive']=true;}return$r;}
}

